"""
    reduceWith takes reducer as first argument, computes a reduction over iterable.
    Think foldl from Haskell.
    reducer is (b -> a -> b)
    Seed is b
    iterable is [a]
    reduceWith is (b -> a -> b) -> b -> [a] -> b
    """
def reduceWith(reducer: Any, seed: Any, iterable: Any) -> object {
    accumulation = seed;
    for value in iterable {
        accumulation = reducer(accumulation, value);
    }
    return accumulation;
}

"""Returns True if the item is a runway visibility range string"""
def is_runway_visibility(item: str) -> bool {
    return (
        (len(item) > 4)
        and (item[0] == "R")
        and ((item[3] == "/") or (item[4] == "/"))
        and item[1:3].isdigit()
    );
}

